 if(b.dataset.jobStage){const choices=JOB_STAGES[b.dataset.jobCurrent]||[];if(!choices.length)return notify('This job is already completed.',true);const values=await requestForm({title:'Update manufacturing job',description:'Production activity is recorded in the audit log. Complete each job before QC.',confirm:'Update job stage',fields:[{name:'to',label:'New job stage',type:'select',options:choices.map(v=>({value:v,label:v.replaceAll('_',' ')}))},{name:'reason',label:'Production notes',type:'textarea',minlength:8,maxlength:800}]});if(!values)return;return action(`/admin/work-orders/${b.dataset.jobStage}/stage`,values,'POST','Manufacturing job stage updated.');}
 if(b.dataset.orderTimeline){try{const d=await api(`/orders/${encodeURIComponent(b.dataset.orderTimeline)}/timeline`);const panel=$('orderTimeline');if(panel)panel.innerHTML=`<div class="tracking-timeline"><h5>Order event history</h5>${d.events.length?d.events.map(e=>`<div class="tracking-event"><i aria-hidden="true"></i><div><strong>${esc(e.event.replaceAll(/[._]/g,' '))}</strong><span>${formatWhen(e.at)}${e.location?' · '+esc(e.location):''}</span></div></div>`).join(''):'No activity recorded'}</div>`;}catch(e){notify(e.message,true)}return;}
 if(b.dataset.openTicket){const values=await requestForm({title:'Contact customer care',description:'Describe an order change, delivery issue, quality concern or refund enquiry. Our team will review your request.',confirm:'Submit service request',fields:[{name:'category',label:'Issue category',type:'select',options:['order_change','artwork','quality','delivery','payment','refund','other'].map(v=>({value:v,label:v.replaceAll('_',' ')}))},{name:'subject',label:'Short subject',minlength:5,maxlength:160},{name:'message',label:'Details of the issue',type:'textarea',minlength:10,maxlength:3000}]});if(!values)return;const result=await action('/tickets',{orderId:b.dataset.openTicket,...values},'POST','Your request has been recorded.');if(result){state.workspaceTab='tickets';await loadWorkspace();}return;}
