 if(b.dataset.ticketStatus){const choices=TICKET_STAGES[b.dataset.ticketCurrent]||[];if(!choices.length)return notify('No further status transition is allowed.',true);const values=await requestForm({title:'Update service request',description:'Status transitions are logged for customer support accountability.',confirm:'Update request',fields:[{name:'status',label:'New status',type:'select',options:choices.map(v=>({value:v,label:v.replaceAll('_',' ')}))}]});if(!values)return;return action(`/tickets/${b.dataset.ticketStatus}/status`,values,'POST','Request status updated.');}
