 if(b.dataset.proof){const values=await requestForm({title:'Submit artwork proof',description:'This is a versioned proof notice, not a file upload. Do not start production until the customer approves the actual artwork.',confirm:'Send proof for approval',fields:[{name:'notes',label:'Proof details and version reference',type:'textarea',minlength:10,maxlength:900,placeholder:'Revision version, design changes, approval instructions and secure artwork reference'}]});if(!values)return;return action('/proofs',{orderId:b.dataset.proof,notes:values.notes},'POST','Design proof sent for customer approval.');}
