 if(b.dataset.refundRequest){const limit=(Number(b.dataset.refundMax)/100).toFixed(2);const values=await requestForm({title:'Request a refund',description:'Refund eligibility, policy deductions and actual payout will be reviewed by finance. Submitting a request does not issue money.',confirm:'Submit refund request',fields:[{name:'amount',label:'Requested refund · ₹',type:'number',step:'.01',min:'.01',max:limit,value:limit},{name:'reason',label:'Reason for refund',type:'textarea',minlength:5,maxlength:800,placeholder:'Describe the issue and the preferred resolution'}]});if(!values)return;return action('/refunds',{paymentId:b.dataset.refundRequest,requestedMinor:Math.round(Number(values.amount)*100),feeMinor:0,reason:values.reason},'POST','Refund request submitted for review.');}
 if(b.dataset.refundApprove||b.dataset.refundReject){const id=b.dataset.refundApprove||b.dataset.refundReject,decision=b.dataset.refundApprove?'approve':'reject';const values=await requestForm({title:`${decision==='approve'?'Approve':'Reject'} refund request`,description:'Verify captured balance, customer terms, policy deductions and independent approval. Deductions must be explained.',confirm:`${decision==='approve'?'Approve':'Reject'} request`,fields:decision==='approve'?[{name:'feeMinorRupees',label:'Deduction / fees retained · ₹',type:'number',min:0,max:Number(b.dataset.refundRequested)/100,step:'.01',value:(Number(b.dataset.refundFee||0)/100).toFixed(2)},{name:'reviewNotes',label:'Decision notes',type:'textarea',required:false,maxlength:900}]:[{name:'reviewNotes',label:'Rejection reason',type:'textarea',required:false,maxlength:900}]});if(!values)return;return action(`/refunds/${id}/${decision}`,{feeMinor:Math.round(Number(values.feeMinorRupees||0)*100),reviewNotes:values.reviewNotes},'POST','Refund review decision saved.');}
